-- V48 — 리그 콜드스타트용 봇 유저 190명 (GROMO-1565)
--
-- 리그는 전역 랭킹(daily_focus_stats 주간 합계)이고 참가 조건이 "미탈퇴 + 닉네임 존재"뿐이라,
-- 봇도 평범한 유저 행으로 넣으면 랭킹·라이브 표시·프로필 통계가 모두 기존 경로를 탄다.
-- 집중 세션은 BotSimulator 가 5분마다 FocusService 를 호출해 실유저와 같은 경로로 쌓는다.
--
-- id 는 전부 md5(고정 접두어 || 자연키)::uuid — 환경(dev/prod)이 달라도 같은 id 가 나오고,
-- 재실행해도 ON CONFLICT 로 걸린다 (scripts/seed-local-debug.sql 의 선례와 같은 방식).
-- UUIDv7 이 아닌 이유: 직접 INSERT 라 @GeneratedUuidV7 이 개입하지 않고, PK 로서 기능 차이가 없다.

-- ── 1) 봇 식별 플래그 ────────────────────────────────────────────────────────
-- 실유저 통계에서 봇을 걷어내고, 나중에 봇을 회수할 때 대상을 특정하는 유일한 근거다.
-- columnDefinition 으로 DB default 를 주는 기존 관례(stat_visibility·last_active_at)와 맞춘다.
ALTER TABLE users ADD COLUMN IF NOT EXISTS is_bot boolean NOT NULL DEFAULT false;

-- BotSimulator 가 매 tick 봇 목록을 뽑는 조회용 부분 인덱스 — 봇 행만 담아 작다.
-- (친구 검색·리그 랭킹은 봇을 그대로 노출하므로 제외 조건을 넣지 않는다.)
CREATE INDEX IF NOT EXISTS idx_users_is_bot ON users (is_bot) WHERE is_bot = true;

-- ── 2) 봇 성향 ──────────────────────────────────────────────────────────────
-- 스케줄을 userId 해시로 도출하지 않고 테이블에 두는 이유: 승인된 명단을 그대로 재현해야 하고,
-- "T4 를 줄여줘" 같은 조정이 배포 없이 UPDATE 로 끝나야 하기 때문이다.
CREATE TABLE IF NOT EXISTS bot_profiles (
    user_id        uuid PRIMARY KEY REFERENCES users (id),
    -- DAWN(04~) / MORNING(08~) / AFTERNOON(13~) / NIGHT(20~, 자정 넘김)
    chronotype     varchar(20) NOT NULL,
    -- POMODORO(25~50분) / MIXED(45~75분) / DEEP(70~110분)
    style          varchar(20) NOT NULL,
    -- 주간 목표 집중 분. 티어 유지 구간(14/28/42/56시간) 안쪽에 둔다.
    weekly_minutes integer NOT NULL,
    -- 주 며칠 집중하는가 (4~6)
    active_days    integer NOT NULL,
    -- 쉬는 요일 비트마스크. 비트 0 = 월요일 … 비트 6 = 일요일.
    rest_day_mask  integer NOT NULL,
    created_at     timestamp(6) with time zone NOT NULL DEFAULT now(),
    CONSTRAINT ck_bot_profiles_chronotype CHECK (chronotype IN ('DAWN', 'MORNING', 'AFTERNOON', 'NIGHT')),
    CONSTRAINT ck_bot_profiles_style CHECK (style IN ('POMODORO', 'MIXED', 'DEEP')),
    CONSTRAINT ck_bot_profiles_weekly_minutes CHECK (weekly_minutes BETWEEN 60 AND 4200),
    CONSTRAINT ck_bot_profiles_active_days CHECK (active_days BETWEEN 1 AND 7),
    CONSTRAINT ck_bot_profiles_rest_day_mask CHECK (rest_day_mask BETWEEN 0 AND 127)
);

