-- 충돌 대상을 id 로 못 박는다. 무대상 DO NOTHING 이면 실유저와 닉네임이 겹칠 때
-- 그 봇만 조용히 빠지고 부수 데이터까지 통째로 누락되는데 마이그레이션은 성공으로 남는다.
ON CONFLICT (id) DO NOTHING;

-- 닉네임 충돌로 조용히 누락되지 않았는지 확인한다. 실패하면 충돌한 닉네임을 바꿔 재배포한다.
DO $$
DECLARE seeded integer;
BEGIN
    SELECT count(*) INTO seeded FROM users WHERE is_bot;
    IF seeded <> 190 THEN
        RAISE EXCEPTION '봇 유저가 190명이 아닙니다 (실제 %). 실유저와 닉네임이 충돌했을 가능성이 높습니다.', seeded;
    END IF;
END $$;

-- ── 6) 유저 부수 행 ─────────────────────────────────────────────────────────
-- AuthService.createUserSideRows 가 실유저에게 만들어 주는 4종. 없으면 승급 보너스 지급이
-- 지갑 없음으로 터진다. 봇 id 집합에서 한 번에 만든다.
INSERT INTO user_wallets (user_id, balance, version, updated_at)
SELECT id, 0, 0, now() FROM users WHERE is_bot = true
ON CONFLICT (user_id) DO NOTHING;
INSERT INTO user_focus_time_settings (user_id, daily_focus_time_goal_minutes, updated_at)
SELECT id, 0, now() FROM users WHERE is_bot = true
ON CONFLICT (user_id) DO NOTHING;

INSERT INTO user_screen_time_settings (user_id, daily_screen_time_goal_minutes,
                                       is_screen_time_permission_granted, created_at, updated_at)
SELECT id, 0, false, now(), now() FROM users WHERE is_bot = true
ON CONFLICT (user_id) DO NOTHING;

-- 알림은 전부 끈다. device_token 이 없어 실제 발송은 어차피 안 되지만, 봇을 대상으로 도는
-- 알림 잡의 조회·집계 비용을 줄이고 의도를 명시해 둔다.
INSERT INTO user_notification_settings (user_id, notification_enabled, sound_enabled,
                                        night_mode_enabled, updated_at)
SELECT id, false, false, false, now() FROM users WHERE is_bot = true
ON CONFLICT (user_id) DO NOTHING;

-- ── 7) 봇이 채택한 과목 ─────────────────────────────────────────────────────
-- 봇마다 자기 직군 풀에서 4~6개를 다르게 고른다. source_occupation_default_tag_id 는
-- 추천에서 왔음을 남긴다(실유저 채택 경로와 동일한 의미).
