JOIN users u ON u.nickname = t.nickname AND u.is_bot = true
JOIN default_tags d ON d.name = t.tag
LEFT JOIN occupation_default_tags odt ON odt.default_tag_id = d.id AND odt.occupation = u.occupation
ON CONFLICT (id) DO NOTHING;

