-- ── 9) 배포된 주의 지나간 날 채우기 ───────────────────────────────────────
-- 주간 정산(V13 임계값)은 월~일 전체를 절대 시간으로 본다. 주중에 배포되면 봇은 그 주의
-- 남은 날만 기록하게 되어 상위 티어가 강등선을 못 채우고 통째로 내려앉는다 — 다음 주엔 다시
-- 올라오므로 티어 분포가 한 주 무너지고 승급 보상까지 헛돈다 (코드리뷰 반영).
--
-- 집계(daily_focus_stats)만 넣으면 /stats/focus 는 채워지는데 /stats/by-category 는
-- 완료 세션을 직접 읽어 비어, 같은 기간의 총합과 과목별 합이 어긋난다 (코드리뷰 반영).
-- 그래서 **세션을 먼저 넣고 집계를 거기서 파생**시켜 두 경로가 같은 원천을 보게 한다.
--
-- 오늘 몫은 배포 시각까지 이미 끝난 세션만 넣으므로 시뮬레이터가 그 뒤로 쌓는 분과 겹치지 않는다.
-- 월요일에 배포되면 오늘(월) 그때까지의 분량만 들어간다.
INSERT INTO focus_sessions (id, user_id, focus_tag_id, status, focus_type,
                            started_at, ended_at, stat_end_at, total_distraction_seconds, created_at)
SELECT md5('gromo-bot-sess-' || s.nickname || '-' || s.day || '-' || s.n)::uuid,
       s.user_id,
       s.focus_tag_id,
       'COMPLETED',
       'INFINITE',
       s.started_at,
       s.started_at + make_interval(mins => s.block_minutes),
       s.started_at + make_interval(mins => s.block_minutes),
       0,
       now()
FROM (
    SELECT p.user_id,
           u.nickname,
           d.day::date AS day,
           g.n,
           -- 마지막 블록이 정수 나눗셈의 나머지를 흡수한다. 균등 분할만 하면 하루 합계가
           -- 일평균보다 최대 몇 분 모자라고, 그 손실이 주간 합계에 쌓인다 (코드리뷰 반영).
           CASE WHEN g.n < plan.blocks THEN plan.block_minutes
                ELSE plan.minutes - (plan.blocks - 1) * plan.block_minutes
           END AS block_minutes,
           -- 성향의 시작 시각에서 출발하되, 그날 소요가 자정을 넘지 않도록 필요하면 앞당긴다.
           -- 자정을 넘기면 집계는 시작일에 전량 귀속하는데 /stats/by-category 는 날짜 경계로
           -- 클리핑해 읽어, 같은 날의 총합과 과목별 합이 어긋난다 (코드리뷰 반영).
           ((d.day::date)::timestamp
                + make_interval(mins => plan.start_minute)
                + make_interval(mins => (g.n - 1) * (plan.block_minutes + 35))
           ) AT TIME ZONE 'Asia/Seoul' AS started_at,
           -- 봇이 채택한 과목을 블록마다 돌아가며 쓴다.
           (SELECT t.id FROM user_focus_tags t
             WHERE t.user_id = p.user_id AND t.deleted_at IS NULL
             ORDER BY t.id
             OFFSET (g.n - 1) % GREATEST(1, (SELECT count(*) FROM user_focus_tags t2
                                              WHERE t2.user_id = p.user_id AND t2.deleted_at IS NULL))
             LIMIT 1) AS focus_tag_id
    FROM bot_profiles p
    JOIN users u ON u.id = p.user_id
    CROSS JOIN generate_series(
            date_trunc('week', (now() AT TIME ZONE 'Asia/Seoul'))::timestamp,
            (now() AT TIME ZONE 'Asia/Seoul')::date::timestamp,
            interval '1 day') AS d(day)
    CROSS JOIN LATERAL (
        SELECT sized.blocks,
               sized.block_minutes,
               sized.minutes,
               -- 성향 시작 시각과 "자정 23시까지 다 끝나는 시작 시각" 중 이른 쪽.
               -- 소요는 집중분(minutes) + 블록 사이 휴식이다.
               GREATEST(0, LEAST(sized.preferred_start,
                                 23 * 60 - (sized.minutes + (sized.blocks - 1) * 35))) AS start_minute
        FROM (
            SELECT daily.minutes,
                   GREATEST(1, ceil(daily.minutes / 80.0)::int) AS blocks,
                   GREATEST(15, (daily.minutes / GREATEST(1, ceil(daily.minutes / 80.0)::int))::int)
                       AS block_minutes,
                   (CASE p.chronotype
                        WHEN 'DAWN' THEN 3
                        WHEN 'MORNING' THEN 8
                        WHEN 'AFTERNOON' THEN 13
                        ELSE 21
                    END) * 60 AS preferred_start
            -- 하루 몫은 일평균 그대로 쓴다. 여기에 일별 난수를 곱하면 그 변동이 주 단위로
            -- 정규화되지 않아(시뮬레이터의 dayFactor 와 달리) 배포 요일에 따라 주간 합계가
            -- 유지 구간을 벗어난다 (코드리뷰 반영). 변동을 빼면 시드 합계는 정확히
            -- 일평균 × 시드된 활동일수 가 되고, 나머지 날은 시뮬레이터가 주간 목표에
            -- 수렴하도록 채우므로 둘을 합치면 주간 목표에 맞는다.
            FROM (SELECT (p.weekly_minutes / p.active_days) AS minutes) daily
        ) sized
    ) plan
    CROSS JOIN LATERAL generate_series(1, plan.blocks) AS g(n)
    -- rest_day_mask 비트 0 = 월요일, ISODOW 는 1 = 월요일
    WHERE (p.rest_day_mask & (1 << (EXTRACT(ISODOW FROM d.day)::int - 1))) = 0
) s
-- **이미 끝난 세션만** 넣는다. 오늘 날짜 전체를 넣으면 오전에 배포했을 때 오후·야간 봇의
-- 아직 시작하지도 않은 세션이 COMPLETED 로 들어가, 집계는 하루치를 다 세는데 과목별 통계는
-- now 상한으로 잘라 읽어 어긋나고 리그 순위에도 미래 집중량이 선반영된다 (코드리뷰 반영).
-- 덕분에 오늘 몫은 '시드(지금까지) + 시뮬레이터(지금부터)' 로 정확히 하루치가 된다.
WHERE s.focus_tag_id IS NOT NULL
  AND s.started_at + make_interval(mins => s.block_minutes) <= now()
ON CONFLICT (id) DO NOTHING;

-- 집계는 방금 넣은 세션에서 그대로 파생시킨다 — 두 통계 경로가 어긋날 여지를 없앤다.
-- 귀속 날짜는 시작 시각의 KST 날짜다(야간 블록이 자정을 넘겨도 시작일로 모은다).
INSERT INTO daily_focus_stats (id, user_id, date, total_focus_seconds, total_distraction_seconds,
                               session_count, is_focus_time_goal_achieved, updated_at)
SELECT md5('gromo-bot-dfs-' || s.user_id::text || '-' || s.day)::uuid,
       s.user_id, s.day, s.total_seconds, 0, s.sessions, false, now()
FROM (
    SELECT fs.user_id,
           ((fs.started_at AT TIME ZONE 'Asia/Seoul')::date) AS day,
           sum(EXTRACT(EPOCH FROM (fs.ended_at - fs.started_at)))::int AS total_seconds,
           count(*)::int AS sessions
    FROM focus_sessions fs
    JOIN users u ON u.id = fs.user_id
    WHERE u.is_bot AND fs.status = 'COMPLETED'
    GROUP BY 1, 2
) s
ON CONFLICT (user_id, date) DO NOTHING;

-- ── 10) 시드된 집중일에서 스트릭 파생 ──────────────────────────────────────
-- 히트맵에는 연속 집중일이 보이는데 /stats/streak 만 0 이면 앞뒤가 안 맞는다. 게다가
-- UserStreakService 는 row 가 없으면 오늘만 반영해 1 부터 시작하고 과거를 소급하지 않아,
-- 시드한 연속일이 영영 복구되지 않는다 (코드리뷰 반영).
--
-- 스트릭 자격일은 그날 누적 집중 10분(600초) 이상이다(UserStreakService.STREAK_MIN_SECONDS).
-- 연속 구간은 gaps-and-islands — 날짜에서 행 번호를 빼면 같은 구간이 같은 값이 된다.
--
-- 현재 스트릭과 최장 스트릭은 따로 센다. 현재 구간 길이를 최장에도 그대로 넣으면, 이번 주에
-- 더 긴 구간이 앞서 있었을 때 최장 기록이 줄어든다 (코드리뷰 반영).
INSERT INTO user_streaks (user_id, streak_count, longest_streak_count, last_session_date, updated_at)
SELECT summary.user_id,
       COALESCE(summary.current_days, 0),
       summary.longest_days,
       summary.last_qualified_day,
       now()
FROM (
    SELECT island.user_id,
           max(island.days) AS longest_days,
           -- 오늘(또는 어제)까지 이어진 구간만 '현재' 스트릭이다. 없으면 0.
           max(island.days) FILTER (
               WHERE island.last_day >= (now() AT TIME ZONE 'Asia/Seoul')::date - 1) AS current_days,
           max(island.last_day) AS last_qualified_day
    FROM (
        SELECT marked.user_id,
               count(*)::int AS days,
               max(marked.date) AS last_day
        FROM (
            SELECT d.user_id,
                   d.date,
                   d.date - (row_number() OVER (PARTITION BY d.user_id ORDER BY d.date))::int AS island_key
            FROM daily_focus_stats d
            JOIN users u ON u.id = d.user_id
            WHERE u.is_bot AND d.total_focus_seconds >= 600
        ) marked
        GROUP BY marked.user_id, marked.island_key
    ) island
    GROUP BY island.user_id
) summary
ON CONFLICT (user_id) DO NOTHING;
